def solve_variation():
    n = 1875
    d_max = 100

    min_edges = float('inf')

    # Try all possible sizes of S_2 from 1 to d_max-1
    for s2 in range(1, d_max):
        s3 = n - 2 - s2
        # Find the smallest m such that m^2 - d_max*m + s3 <= 0
        min_m = None
        for m in range(1, d_max + 1):
            if m*m - d_max*m + s3 <= 0:
                min_m = m
                break

        if min_m is not None:
            edges = 1 + s2 + s3 + min_m * (min_m - 1) // 2
            if edges < min_edges:
                min_edges = edges

    print(f"Min edges: {min_edges}")

solve_variation()

